369|/**
370| * This routine normalizes a response. This includes removing "irrelevant"
371| * records from the answer and additional sections and (re)synthesizing
372| * CNAMEs from DNAMEs, if present.
373| *
374| * @param pkt: packet.
375| * @param msg: msg to normalize.
376| * @param qinfo: original query.
377| * @param region: where to allocate synthesized CNAMEs.
378| * @param env: module env with config options.
379| * @return 0 on error.
380| */
381|static int
382|scrub_normalize(sldns_buffer* pkt, struct msg_parse* msg, 
383|	struct query_info* qinfo, struct regional* region,
384|	struct module_env* env)
385|{
386|	uint8_t* sname = qinfo->qname;
387|	size_t snamelen = qinfo->qname_len;
388|	struct rrset_parse* rrset, *prev, *nsset=NULL;
389|
390|	if(FLAGS_GET_RCODE(msg->flags) != LDNS_RCODE_NOERROR &&
391|		FLAGS_GET_RCODE(msg->flags) != LDNS_RCODE_NXDOMAIN)
392|		return 1;
393|
394|	/* For the ANSWER section, remove all "irrelevant" records and add
395|	 * synthesized CNAMEs from DNAMEs
396|	 * This will strip out-of-order CNAMEs as well. */
397|
398|	/* walk through the parse packet rrset list, keep track of previous
399|	 * for insert and delete ease, and examine every RRset */
400|	prev = NULL;
401|	rrset = msg->rrset_first;
402|	while(rrset && rrset->section == LDNS_SECTION_ANSWER) {
403|		if(rrset->type == LDNS_RR_TYPE_DNAME && 
404|			pkt_strict_sub(pkt, sname, rrset->dname)) {
405|			/* check if next rrset is correct CNAME. else,
406|			 * synthesize a CNAME */
407|			struct rrset_parse* nx = rrset->rrset_all_next;
408|			uint8_t alias[LDNS_MAX_DOMAINLEN+1];
409|			size_t aliaslen = 0;
410|			if(rrset->rr_count != 1) {
411|				verbose(VERB_ALGO, "Found DNAME rrset with "
412|					"size > 1: %u", 
413|					(unsigned)rrset->rr_count);
414|				return 0;
415|			}
416|			if(!synth_cname(sname, snamelen, rrset, alias, 
417|				&aliaslen, pkt)) {
418|				verbose(VERB_ALGO, "synthesized CNAME "
419|					"too long");
420|				return 0;
421|			}
422|			if(nx && nx->type == LDNS_RR_TYPE_CNAME && 
423|			   dname_pkt_compare(pkt, sname, nx->dname) == 0) {
424|				/* check next cname */
425|				uint8_t* t = NULL;
426|				size_t tlen = 0;
427|				if(!parse_get_cname_target(nx, &t, &tlen, pkt))
428|					return 0;
429|				if(dname_pkt_compare(pkt, alias, t) == 0) {
430|					/* it's OK and better capitalized */
431|					prev = rrset;
432|					rrset = nx;
433|					continue;
434|				}
435|				/* synth ourselves */
436|			}
437|			/* synth a CNAME rrset */
438|			prev = synth_cname_rrset(&sname, &snamelen, alias, 
439|				aliaslen, region, msg, rrset, rrset, nx, pkt);
440|			if(!prev) {
441|				log_err("out of memory synthesizing CNAME");
442|				return 0;
443|			}
444|			/* FIXME: resolve the conflict between synthesized 
445|			 * CNAME ttls and the cache. */
446|			rrset = nx;
447|			continue;
448|
449|		}
450|
451|		/* The only records in the ANSWER section not allowed to */
452|		if(dname_pkt_compare(pkt, sname, rrset->dname) != 0) {
453|			remove_rrset("normalize: removing irrelevant RRset:", 
454|				pkt, msg, prev, &rrset);
455|			continue;
456|		}
457|
458|		/* Follow the CNAME chain. */
459|		if(rrset->type == LDNS_RR_TYPE_CNAME) {
460|			struct rrset_parse* nx = rrset->rrset_all_next;
461|			uint8_t* oldsname = sname;
462|			/* see if the next one is a DNAME, if so, swap them */
463|			if(nx && nx->section == LDNS_SECTION_ANSWER &&
464|				nx->type == LDNS_RR_TYPE_DNAME &&
465|				nx->rr_count == 1 &&
466|				pkt_strict_sub(pkt, sname, nx->dname)) {
467|				/* there is a DNAME after this CNAME, it 
468|				 * is in the ANSWER section, and the DNAME
469|				 * applies to the name we cover */
470|				/* check if the alias of the DNAME equals
471|				 * this CNAME */
472|				uint8_t alias[LDNS_MAX_DOMAINLEN+1];
473|				size_t aliaslen = 0;
474|				uint8_t* t = NULL;
475|				size_t tlen = 0;
476|				if(synth_cname(sname, snamelen, nx, alias,
477|					&aliaslen, pkt) &&
478|					parse_get_cname_target(rrset, &t, &tlen, pkt) &&
479|			   		dname_pkt_compare(pkt, alias, t) == 0) {
480|					/* the synthesized CNAME equals the
481|					 * current CNAME.  This CNAME is the
482|					 * one that the DNAME creates, and this
483|					 * CNAME is better capitalised */
484|					verbose(VERB_ALGO, "normalize: re-order of DNAME and its CNAME");
485|					if(prev) prev->rrset_all_next = nx;
486|					else msg->rrset_first = nx;
487|					if(nx->rrset_all_next == NULL)
488|						msg->rrset_last = rrset;
489|					rrset->rrset_all_next =
490|						nx->rrset_all_next;
491|					nx->rrset_all_next = rrset;
492|					/* prev = nx; unused, enable if there
493|					 * is other rrset removal code after
494|					 * this */
495|				}
496|			}
497|
498|			/* move to next name in CNAME chain */
499|			if(!parse_get_cname_target(rrset, &sname, &snamelen, pkt))
500|				return 0;
501|			prev = rrset;
502|			rrset = rrset->rrset_all_next;
503|			/* in CNAME ANY response, can have data after CNAME */
504|			if(qinfo->qtype == LDNS_RR_TYPE_ANY) {
505|				while(rrset && rrset->section ==
506|					LDNS_SECTION_ANSWER &&
507|					dname_pkt_compare(pkt, oldsname,
508|					rrset->dname) == 0) {
509|					prev = rrset;
510|					rrset = rrset->rrset_all_next;
511|				}
512|			}
513|			continue;
514|		}
515|
516|		/* Otherwise, make sure that the RRset matches the qtype. */
517|		if(qinfo->qtype != LDNS_RR_TYPE_ANY && 
518|			qinfo->qtype != rrset->type) {
519|			remove_rrset("normalize: removing irrelevant RRset:", 
520|				pkt, msg, prev, &rrset);
521|			continue;
522|		}
523|
524|		/* Mark the additional names from relevant rrset as OK. */
525|		/* only for RRsets that match the query name, other ones
526|		 * will be removed by sanitize, so no additional for them */
527|		if(dname_pkt_compare(pkt, qinfo->qname, rrset->dname) == 0)
528|			mark_additional_rrset(pkt, msg, rrset);
529|		
530|		prev = rrset;
531|		rrset = rrset->rrset_all_next;
532|	}
533|
534|	/* Mark additional names from AUTHORITY */
535|	while(rrset && rrset->section == LDNS_SECTION_AUTHORITY) {
536|		/* protect internals of recursor by making sure to del these */
537|		if(rrset->type==LDNS_RR_TYPE_DNAME ||
538|			rrset->type==LDNS_RR_TYPE_CNAME ||
539|			rrset->type==LDNS_RR_TYPE_A ||
540|			rrset->type==LDNS_RR_TYPE_AAAA) {
541|			remove_rrset("normalize: removing irrelevant "
542|				"RRset:", pkt, msg, prev, &rrset);
543|			continue;
544|		}
545|		/* Allowed list of types in the authority section */
546|		if(env->cfg->harden_unknown_additional &&
547|			!type_allowed_in_authority_section(rrset->type)) {
548|			remove_rrset("normalize: removing irrelevant "
549|				"RRset:", pkt, msg, prev, &rrset);
550|			continue;
551|		}
552|		/* only one NS set allowed in authority section */
553|		if(rrset->type==LDNS_RR_TYPE_NS) {
554|			/* NS set must be pertinent to the query */
555|			if(!sub_of_pkt(pkt, qinfo->qname, rrset->dname)) {
556|				remove_rrset("normalize: removing irrelevant "
557|					"RRset:", pkt, msg, prev, &rrset);
558|				continue;
559|			}
560|			/* we don't want NS sets for NXDOMAIN answers,
561|			 * because they could contain poisonous contents,
562|			 * from. eg. fragmentation attacks, inserted after
563|			 * long RRSIGs in the packet get to the packet
564|			 * border and such */
565|			/* also for NODATA answers */
566|			if(FLAGS_GET_RCODE(msg->flags) == LDNS_RCODE_NXDOMAIN ||
567|			   (FLAGS_GET_RCODE(msg->flags) == LDNS_RCODE_NOERROR
568|			    && soa_in_auth(msg) && msg->an_rrsets == 0)) {
569|				remove_rrset("normalize: removing irrelevant "
570|					"RRset:", pkt, msg, prev, &rrset);
571|				continue;
572|			}
573|			if(nsset == NULL) {
574|				nsset = rrset;
575|			} else {
576|				remove_rrset("normalize: removing irrelevant "
577|					"RRset:", pkt, msg, prev, &rrset);
578|				continue;
579|			}
580|		}
581|		/* if this is type DS and we query for type DS we just got
582|		 * a referral answer for our type DS query, fix packet */
583|		if(rrset->type==LDNS_RR_TYPE_DS &&
584|			qinfo->qtype == LDNS_RR_TYPE_DS &&
585|			dname_pkt_compare(pkt, qinfo->qname, rrset->dname) == 0) {
586|			rrset->section = LDNS_SECTION_ANSWER;
587|			msg->ancount = rrset->rr_count + rrset->rrsig_count;
588|			msg->nscount = 0;
589|			msg->arcount = 0;
590|			msg->an_rrsets = 1;
591|			msg->ns_rrsets = 0;
592|			msg->ar_rrsets = 0;
593|			msg->rrset_count = 1;
594|			msg->rrset_first = rrset;
595|			msg->rrset_last = rrset;
596|			rrset->rrset_all_next = NULL;
597|			return 1;
598|		}
599|		mark_additional_rrset(pkt, msg, rrset);
600|		prev = rrset;
601|		rrset = rrset->rrset_all_next;
602|	}
603|
604|	/* For each record in the additional section, remove it if it is an
605|	 * address record and not in the collection of additional names 
606|	 * found in ANSWER and AUTHORITY. */
607|	/* These records have not been marked OK previously */
608|	while(rrset && rrset->section == LDNS_SECTION_ADDITIONAL) {
609|		if(rrset->type==LDNS_RR_TYPE_A || 
610|			rrset->type==LDNS_RR_TYPE_AAAA) 
611|		{
612|			if((rrset->flags & RRSET_SCRUB_OK)) {
613|				/* remove flag to clean up flags variable */
614|				rrset->flags &= ~RRSET_SCRUB_OK;
615|			} else {
616|				remove_rrset("normalize: removing irrelevant "
617|					"RRset:", pkt, msg, prev, &rrset);
618|				continue;
619|			}
620|		}
621|		/* protect internals of recursor by making sure to del these */
622|		if(rrset->type==LDNS_RR_TYPE_DNAME || 
623|			rrset->type==LDNS_RR_TYPE_CNAME ||
624|			rrset->type==LDNS_RR_TYPE_NS) {
625|			remove_rrset("normalize: removing irrelevant "
626|				"RRset:", pkt, msg, prev, &rrset);
627|			continue;
628|		}
629|		/* Allowed list of types in the additional section */
630|		if(env->cfg->harden_unknown_additional &&
631|			!type_allowed_in_additional_section(rrset->type)) {
632|			remove_rrset("normalize: removing irrelevant "
633|				"RRset:", pkt, msg, prev, &rrset);
634|			continue;
635|		}
636|		prev = rrset;
637|		rrset = rrset->rrset_all_next;
638|	}
639|	
640|	return 1;
641|}
642|
643|/**
644| * Store potential poison in the cache (only if hardening disabled).
645| * The rrset is stored in the cache but removed from the message.
646| * So that it will be used for infrastructure purposes, but not be 
647| * returned to the client.
648| * @param pkt: packet
649| * @param msg: message parsed
650| * @param env: environment with cache
651| * @param rrset: to store.
652| */
653|static void
654|store_rrset(sldns_buffer* pkt, struct msg_parse* msg, struct module_env* env,
655|	struct rrset_parse* rrset)
656|{
657|	struct ub_packed_rrset_key* k;
658|	struct packed_rrset_data* d;
659|	struct rrset_ref ref;
660|	time_t now = *env->now;
661|
662|	k = alloc_special_obtain(env->alloc);
663|	if(!k)
664|		return;
665|	k->entry.data = NULL;
666|	if(!parse_copy_decompress_rrset(pkt, msg, rrset, NULL, k)) {
667|		alloc_special_release(env->alloc, k);
668|		return;
669|	}
670|	d = (struct packed_rrset_data*)k->entry.data;
671|	packed_rrset_ttl_add(d, now);
672|	ref.key = k;
673|	ref.id = k->id;
674|	/*ignore ret: it was in the cache, ref updated */
675|	(void)rrset_cache_update(env->rrset_cache, &ref, env->alloc, now);
676|}
677|
678|/**
679| * Check if right hand name in NSEC is within zone
680| * @param pkt: the packet buffer for decompression.
681| * @param rrset: the NSEC rrset
682| * @param zonename: the zone name.
683| * @return true if BAD.
684| */
685|static int sanitize_nsec_is_overreach(sldns_buffer* pkt,
686|	struct rrset_parse* rrset, uint8_t* zonename)
687|{
688|	struct rr_parse* rr;
689|	uint8_t* rhs;
690|	size_t len;
691|	log_assert(rrset->type == LDNS_RR_TYPE_NSEC);
692|	for(rr = rrset->rr_first; rr; rr = rr->next) {
693|		size_t pos = sldns_buffer_position(pkt);
694|		size_t rhspos;
695|		rhs = rr->ttl_data+4+2;
696|		len = sldns_read_uint16(rr->ttl_data+4);
697|		rhspos = rhs-sldns_buffer_begin(pkt);
698|		sldns_buffer_set_position(pkt, rhspos);
699|		if(pkt_dname_len(pkt) == 0) {
700|			/* malformed */
701|			sldns_buffer_set_position(pkt, pos);
702|			return 1;
703|		}
704|		if(sldns_buffer_position(pkt)-rhspos > len) {
705|			/* outside of rdata boundaries */
706|			sldns_buffer_set_position(pkt, pos);
707|			return 1;
708|		}
709|		sldns_buffer_set_position(pkt, pos);
710|		if(!pkt_sub(pkt, rhs, zonename)) {
711|			/* overreaching */
712|			return 1;
713|		}
714|	}
715|	/* all NSEC RRs OK */
716|	return 0;
717|}
718|
719|/** Remove individual RRs, if the length is wrong. Returns true if the RRset
720| * has been removed. */
721|static int
722|scrub_sanitize_rr_length(sldns_buffer* pkt, struct msg_parse* msg,
723|	struct rrset_parse* prev, struct rrset_parse** rrset, int* added_ede,
724|	struct module_qstate* qstate)
725|{
726|	struct rr_parse* rr, *rr_prev = NULL;
727|	for(rr = (*rrset)->rr_first; rr; rr = rr->next) {
728|
729|		/* Sanity check for length of records
730|		 * An A record should be 6 bytes only
731|		 * (2 bytes for length and 4 for IPv4 addr)*/
732|		if((*rrset)->type == LDNS_RR_TYPE_A && rr->size != 6 ) {
733|			if(!*added_ede) {
734|				*added_ede = 1;
735|				errinf_ede(qstate, "sanitize: records of inappropriate length have been removed.",
736|					LDNS_EDE_OTHER);
737|			}
738|			if(msgparse_rrset_remove_rr("sanitize: removing type A RR of inappropriate length:",
739|				pkt, *rrset, rr_prev, rr, NULL, 0)) {
740|				remove_rrset("sanitize: removing type A RRset of inappropriate length:",
741|					pkt, msg, prev, rrset);
742|				return 1;
743|			}
744|			continue;
745|		}
746|
747|		/* Sanity check for length of records
748|		 * An AAAA record should be 18 bytes only
749|		 * (2 bytes for length and 16 for IPv6 addr)*/
750|		if((*rrset)->type == LDNS_RR_TYPE_AAAA && rr->size != 18 ) {
751|			if(!*added_ede) {
752|				*added_ede = 1;
753|				errinf_ede(qstate, "sanitize: records of inappropriate length have been removed.",
754|					LDNS_EDE_OTHER);
755|			}
756|			if(msgparse_rrset_remove_rr("sanitize: removing type AAAA RR of inappropriate length:",
757|				pkt, *rrset, rr_prev, rr, NULL, 0)) {
758|				remove_rrset("sanitize: removing type AAAA RRset of inappropriate length:",
759|					pkt, msg, prev, rrset);
760|				return 1;
761|			}
762|			continue;
763|		}
764|		rr_prev = rr;
765|	}
766|	return 0;
767|}
768|
769|/**
770| * Given a response event, remove suspect RRsets from the response.
771| * "Suspect" rrsets are potentially poison. Note that this routine expects
772| * the response to be in a "normalized" state -- that is, all "irrelevant"
773| * RRsets have already been removed, CNAMEs are in order, etc.
774| *
775| * @param pkt: packet.
776| * @param msg: msg to normalize.
777| * @param qinfo: the question originally asked.
778| * @param zonename: name of server zone.
779| * @param env: module environment with config and cache.
780| * @param ie: iterator environment with private address data.
781| * @param qstate: for setting errinf for EDE error messages.
782| * @return 0 on error.
783| */
784|static int
785|scrub_sanitize(sldns_buffer* pkt, struct msg_parse* msg, 
786|	struct query_info* qinfo, uint8_t* zonename, struct module_env* env,
787|	struct iter_env* ie, struct module_qstate* qstate)
788|{
789|	int del_addi = 0; /* if additional-holding rrsets are deleted, we
790|		do not trust the normalized additional-A-AAAA any more */
791|	int added_rrlen_ede = 0;
792|	struct rrset_parse* rrset, *prev;
793|	prev = NULL;
794|	rrset = msg->rrset_first;
795|
796|	/* the first DNAME is allowed to stay. It needs checking before
797|	 * it can be used from the cache. After normalization, an initial 
798|	 * DNAME will have a correctly synthesized CNAME after it. */
799|	if(rrset && rrset->type == LDNS_RR_TYPE_DNAME && 
800|		rrset->section == LDNS_SECTION_ANSWER &&
801|		pkt_strict_sub(pkt, qinfo->qname, rrset->dname) &&
802|		pkt_sub(pkt, rrset->dname, zonename)) {
803|		prev = rrset; /* DNAME allowed to stay in answer section */
804|		rrset = rrset->rrset_all_next;
805|	}
806|	
807|	/* remove all records from the answer section that are 
808|	 * not the same domain name as the query domain name.
809|	 * The answer section should contain rrsets with the same name
810|	 * as the question. For DNAMEs a CNAME has been synthesized.
811|	 * Wildcards have the query name in answer section.
812|	 * ANY queries get query name in answer section.
813|	 * Remainders of CNAME chains are cut off and resolved by iterator. */
814|	while(rrset && rrset->section == LDNS_SECTION_ANSWER) {
815|		if(dname_pkt_compare(pkt, qinfo->qname, rrset->dname) != 0) {
816|			if(has_additional(rrset->type)) del_addi = 1;
817|			remove_rrset("sanitize: removing extraneous answer "
818|				"RRset:", pkt, msg, prev, &rrset);
819|			continue;
820|		}
821|		prev = rrset;
822|		rrset = rrset->rrset_all_next;
823|	}
824|
825|	/* At this point, we brutally remove ALL rrsets that aren't 
826|	 * children of the originating zone. The idea here is that, 
827|	 * as far as we know, the server that we contacted is ONLY 
828|	 * authoritative for the originating zone. It, of course, MAY 
829|	 * be authoritative for any other zones, and of course, MAY 
830|	 * NOT be authoritative for some subdomains of the originating 
831|	 * zone. */
832|	prev = NULL;
833|	rrset = msg->rrset_first;
834|	while(rrset) {
835|
836|		/* Sanity check for length of records */
837|		if(rrset->type == LDNS_RR_TYPE_A ||
838|			rrset->type == LDNS_RR_TYPE_AAAA) {
839|			if(scrub_sanitize_rr_length(pkt, msg, prev, &rrset,
840|				&added_rrlen_ede, qstate))
841|				continue;
842|		}
843|
844|		/* remove private addresses */
845|		if( (rrset->type == LDNS_RR_TYPE_A || 
846|			rrset->type == LDNS_RR_TYPE_AAAA)) {
847|
848|			/* do not set servfail since this leads to too
849|			 * many drops of other people using rfc1918 space */
850|			/* also do not remove entire rrset, unless all records
851|			 * in it are bad */
852|			if(priv_rrset_bad(ie->priv, pkt, rrset)) {
853|				remove_rrset(NULL, pkt, msg, prev, &rrset);
854|				continue;
855|			}
856|		}
857|		
858|		/* skip DNAME records -- they will always be followed by a 
859|		 * synthesized CNAME, which will be relevant.
860|		 * FIXME: should this do something differently with DNAME 
861|		 * rrsets NOT in Section.ANSWER? */
862|		/* But since DNAME records are also subdomains of the zone,
863|		 * same check can be used */
864|
865|		if(!pkt_sub(pkt, rrset->dname, zonename)) {
866|			if(msg->an_rrsets == 0 && 
867|				rrset->type == LDNS_RR_TYPE_NS && 
868|				rrset->section == LDNS_SECTION_AUTHORITY &&
869|				FLAGS_GET_RCODE(msg->flags) == 
870|				LDNS_RCODE_NOERROR && !soa_in_auth(msg) &&
871|				sub_of_pkt(pkt, zonename, rrset->dname)) {
872|				/* noerror, nodata and this NS rrset is above
873|				 * the zone. This is LAME! 
874|				 * Leave in the NS for lame classification. */
875|				/* remove everything from the additional
876|				 * (we dont want its glue that was approved
877|				 * during the normalize action) */
878|				del_addi = 1;
879|			} else if(!env->cfg->harden_glue && (
880|				rrset->type == LDNS_RR_TYPE_A ||
881|				rrset->type == LDNS_RR_TYPE_AAAA)) {
882|				/* store in cache! Since it is relevant
883|				 * (from normalize) it will be picked up 
884|				 * from the cache to be used later */
885|				store_rrset(pkt, msg, env, rrset);
886|				remove_rrset("sanitize: storing potential "
887|				"poison RRset:", pkt, msg, prev, &rrset);
888|				continue;
889|			} else {
890|				if(has_additional(rrset->type)) del_addi = 1;
891|				remove_rrset("sanitize: removing potential "
892|				"poison RRset:", pkt, msg, prev, &rrset);
893|				continue;
894|			}
895|		}
896|		if(del_addi && rrset->section == LDNS_SECTION_ADDITIONAL) {
897|			remove_rrset("sanitize: removing potential "
898|			"poison reference RRset:", pkt, msg, prev, &rrset);
899|			continue;
900|		}
901|		/* check if right hand side of NSEC is within zone */
902|		if(rrset->type == LDNS_RR_TYPE_NSEC &&
903|			sanitize_nsec_is_overreach(pkt, rrset, zonename)) {
904|			remove_rrset("sanitize: removing overreaching NSEC "
905|				"RRset:", pkt, msg, prev, &rrset);
906|			continue;
907|		}
908|		prev = rrset;
909|		rrset = rrset->rrset_all_next;
910|	}
911|	return 1;
912|}
913|
914|int 
915|scrub_message(sldns_buffer* pkt, struct msg_parse* msg, 
916|	struct query_info* qinfo, uint8_t* zonename, struct regional* region,
917|	struct module_env* env, struct module_qstate* qstate,
918|	struct iter_env* ie)
919|{
920|	/* basic sanity checks */
921|	log_nametypeclass(VERB_ALGO, "scrub for", zonename, LDNS_RR_TYPE_NS, 
922|		qinfo->qclass);
923|	if(msg->qdcount > 1)
924|		return 0;
925|	if( !(msg->flags&BIT_QR) )
926|		return 0;
927|	msg->flags &= ~(BIT_AD|BIT_Z); /* force off bit AD and Z */
928|	
929|	/* make sure that a query is echoed back when NOERROR or NXDOMAIN */
930|	/* this is not required for basic operation but is a forgery 
931|	 * resistance (security) feature */
932|	if((FLAGS_GET_RCODE(msg->flags) == LDNS_RCODE_NOERROR ||
933|		FLAGS_GET_RCODE(msg->flags) == LDNS_RCODE_NXDOMAIN) &&
934|		msg->qdcount == 0)
935|		return 0;
936|
937|	/* if a query is echoed back, make sure it is correct. Otherwise,
938|	 * this may be not a reply to our query. */
939|	if(msg->qdcount == 1) {
940|		if(dname_pkt_compare(pkt, msg->qname, qinfo->qname) != 0)
941|			return 0;
942|		if(msg->qtype != qinfo->qtype || msg->qclass != qinfo->qclass)
943|			return 0;
944|	}
945|
946|	/* normalize the response, this cleans up the additional.  */
947|	if(!scrub_normalize(pkt, msg, qinfo, region, env))
948|		return 0;
949|	/* delete all out-of-zone information */
950|	if(!scrub_sanitize(pkt, msg, qinfo, zonename, env, ie, qstate))
951|		return 0;
952|	return 1;
953|}

4031|static void
4032|process_response(struct module_qstate* qstate, struct iter_qstate* iq, 
4033|	struct iter_env* ie, int id, struct outbound_entry* outbound,
4034|	enum module_ev event)
4035|{
4036|	struct msg_parse* prs;
4037|	struct edns_data edns;
4038|	sldns_buffer* pkt;
4039|
4040|	verbose(VERB_ALGO, "process_response: new external response event");
4041|	iq->response = NULL;
4042|	iq->state = QUERY_RESP_STATE;
4043|	if(event == module_event_noreply || event == module_event_error) {
4044|		if(event == module_event_noreply && iq->timeout_count >= 3 &&
4045|			qstate->env->cfg->use_caps_bits_for_id &&
4046|			!iq->caps_fallback && !is_caps_whitelisted(ie, iq)) {
4047|			/* start fallback */
4048|			iq->caps_fallback = 1;
4049|			iq->caps_server = 0;
4050|			iq->caps_reply = NULL;
4051|			iq->caps_response = NULL;
4052|			iq->caps_minimisation_state = DONOT_MINIMISE_STATE;
4053|			iq->state = QUERYTARGETS_STATE;
4054|			iq->num_current_queries--;
4055|			/* need fresh attempts for the 0x20 fallback, if
4056|			 * that was the cause for the failure */
4057|			iter_dec_attempts(iq->dp, 3, ie->outbound_msg_retry);
4058|			verbose(VERB_DETAIL, "Capsforid: timeouts, starting fallback");
4059|			goto handle_it;
4060|		}
4061|		goto handle_it;
4062|	}
4063|	if( (event != module_event_reply && event != module_event_capsfail)
4064|		|| !qstate->reply) {
4065|		log_err("Bad event combined with response");
4066|		outbound_list_remove(&iq->outlist, outbound);
4067|		errinf(qstate, "module iterator received wrong internal event with a response message");
4068|		(void)error_response(qstate, id, LDNS_RCODE_SERVFAIL);
4069|		return;
4070|	}
4071|
4072|	/* parse message */
4073|	fill_fail_addr(iq, &qstate->reply->remote_addr,
4074|		qstate->reply->remote_addrlen);
4075|	prs = (struct msg_parse*)regional_alloc(qstate->env->scratch, 
4076|		sizeof(struct msg_parse));
4077|	if(!prs) {
4078|		log_err("out of memory on incoming message");
4079|		/* like packet got dropped */
4080|		goto handle_it;
4081|	}
4082|	memset(prs, 0, sizeof(*prs));
4083|	memset(&edns, 0, sizeof(edns));
4084|	pkt = qstate->reply->c->buffer;
4085|	sldns_buffer_set_position(pkt, 0);
4086|	if(parse_packet(pkt, prs, qstate->env->scratch) != LDNS_RCODE_NOERROR) {
4087|		verbose(VERB_ALGO, "parse error on reply packet");
4088|		iq->parse_failures++;
4089|		goto handle_it;
4090|	}
4091|	/* edns is not examined, but removed from message to help cache */
4092|	if(parse_extract_edns_from_response_msg(prs, &edns, qstate->env->scratch) !=
4093|		LDNS_RCODE_NOERROR) {
4094|		iq->parse_failures++;
4095|		goto handle_it;
4096|	}
4097|
4098|	/* Copy the edns options we may got from the back end */
4099|	if(edns.opt_list_in) {
4100|		qstate->edns_opts_back_in = edns_opt_copy_region(edns.opt_list_in,
4101|			qstate->region);
4102|		if(!qstate->edns_opts_back_in) {
4103|			log_err("out of memory on incoming message");
4104|			/* like packet got dropped */
4105|			goto handle_it;
4106|		}
4107|		if(!inplace_cb_edns_back_parsed_call(qstate->env, qstate)) {
4108|			log_err("unable to call edns_back_parsed callback");
4109|			goto handle_it;
4110|		}
4111|	}
4112|
4113|	/* remove CD-bit, we asked for in case we handle validation ourself */
4114|	prs->flags &= ~BIT_CD;
4115|
4116|	/* normalize and sanitize: easy to delete items from linked lists */
4117|	if(!scrub_message(pkt, prs, &iq->qinfo_out, iq->dp->name, 
4118|		qstate->env->scratch, qstate->env, qstate, ie)) {
4119|		/* if 0x20 enabled, start fallback, but we have no message */
4120|		if(event == module_event_capsfail && !iq->caps_fallback) {
4121|			iq->caps_fallback = 1;
4122|			iq->caps_server = 0;
4123|			iq->caps_reply = NULL;
4124|			iq->caps_response = NULL;
4125|			iq->caps_minimisation_state = DONOT_MINIMISE_STATE;
4126|			iq->state = QUERYTARGETS_STATE;
4127|			iq->num_current_queries--;
4128|			verbose(VERB_DETAIL, "Capsforid: scrub failed, starting fallback with no response");
4129|		}
4130|		iq->scrub_failures++;
4131|		goto handle_it;
4132|	}
4133|
4134|	/* allocate response dns_msg in region */
4135|	iq->response = dns_alloc_msg(pkt, prs, qstate->region);
4136|	if(!iq->response)
4137|		goto handle_it;
4138|	log_query_info(VERB_DETAIL, "response for", &qstate->qinfo);
4139|	log_name_addr(VERB_DETAIL, "reply from", iq->dp->name,
4140|		&qstate->reply->remote_addr, qstate->reply->remote_addrlen);
4141|	if(verbosity >= VERB_ALGO)
4142|		log_dns_msg("incoming scrubbed packet:", &iq->response->qinfo, 
4143|			iq->response->rep);
4144|	
4145|	if(event == module_event_capsfail || iq->caps_fallback) {
4146|		if(qstate->env->cfg->qname_minimisation &&
4147|			iq->minimisation_state != DONOT_MINIMISE_STATE) {
4148|			/* Skip QNAME minimisation for next query, since that
4149|			 * one has to match the current query. */
4150|			iq->minimisation_state = SKIP_MINIMISE_STATE;
4151|		}
4152|		/* for fallback we care about main answer, not additionals */
4153|		/* removing that makes comparison more likely to succeed */
4154|		caps_strip_reply(iq->response->rep);
4155|
4156|		if(iq->caps_fallback &&
4157|			iq->caps_minimisation_state != iq->minimisation_state) {
4158|			/* QNAME minimisation state has changed, restart caps
4159|			 * fallback. */
4160|			iq->caps_fallback = 0;
4161|		}
4162|
4163|		if(!iq->caps_fallback) {
4164|			/* start fallback */
4165|			iq->caps_fallback = 1;
4166|			iq->caps_server = 0;
4167|			iq->caps_reply = iq->response->rep;
4168|			iq->caps_response = iq->response;
4169|			iq->caps_minimisation_state = iq->minimisation_state;
4170|			iq->state = QUERYTARGETS_STATE;
4171|			iq->num_current_queries--;
4172|			verbose(VERB_DETAIL, "Capsforid: starting fallback");
4173|			goto handle_it;
4174|		} else {
4175|			/* check if reply is the same, otherwise, fail */
4176|			if(!iq->caps_reply) {
4177|				iq->caps_reply = iq->response->rep;
4178|				iq->caps_response = iq->response;
4179|				iq->caps_server = -1; /*become zero at ++,
4180|				so that we start the full set of trials */
4181|			} else if(caps_failed_rcode(iq->caps_reply) &&
4182|				!caps_failed_rcode(iq->response->rep)) {
4183|				/* prefer to upgrade to non-SERVFAIL */
4184|				iq->caps_reply = iq->response->rep;
4185|				iq->caps_response = iq->response;
4186|			} else if(!caps_failed_rcode(iq->caps_reply) &&
4187|				caps_failed_rcode(iq->response->rep)) {
4188|				/* if we have non-SERVFAIL as answer then 
4189|				 * we can ignore SERVFAILs for the equality
4190|				 * comparison */
4191|				/* no instructions here, skip other else */
4192|			} else if(caps_failed_rcode(iq->caps_reply) &&
4193|				caps_failed_rcode(iq->response->rep)) {
4194|				/* failure is same as other failure in fallbk*/
4195|				/* no instructions here, skip other else */
4196|			} else if(!reply_equal(iq->response->rep, iq->caps_reply,
4197|				qstate->env->scratch)) {
4198|				verbose(VERB_DETAIL, "Capsforid fallback: "
4199|					"getting different replies, failed");
4200|				outbound_list_remove(&iq->outlist, outbound);
4201|				errinf(qstate, "0x20 failed, then got different replies in fallback");
4202|				(void)error_response(qstate, id, 
4203|					LDNS_RCODE_SERVFAIL);
4204|				return;
4205|			}
4206|			/* continue the fallback procedure at next server */
4207|			iq->caps_server++;
4208|			iq->state = QUERYTARGETS_STATE;
4209|			iq->num_current_queries--;
4210|			verbose(VERB_DETAIL, "Capsforid: reply is equal. "
4211|				"go to next fallback");
4212|			goto handle_it;
4213|		}
4214|	}
4215|	iq->caps_fallback = 0; /* if we were in fallback, 0x20 is OK now */
4216|
4217|handle_it:
4218|	outbound_list_remove(&iq->outlist, outbound);
4219|	iter_handle(qstate, iq, ie, id);
4220|}

385|static int
386|prep_data(struct module_qstate* qstate, struct sldns_buffer* buf)
387|{
388|	uint64_t timestamp, expiry;
389|	size_t oldlim;
390|	struct edns_data edns;
391|	memset(&edns, 0, sizeof(edns));
392|	edns.edns_present = 1;
393|	edns.bits = EDNS_DO;
394|	edns.ext_rcode = 0;
395|	edns.edns_version = EDNS_ADVERTISED_VERSION;
396|	edns.udp_size = EDNS_ADVERTISED_SIZE;
397|
398|	if(!qstate->return_msg || !qstate->return_msg->rep)
399|		return 0;
400|	/* do not store failures like SERVFAIL in the cachedb, this avoids
401|	 * overwriting expired, valid, content with broken content. */
402|	if(FLAGS_GET_RCODE(qstate->return_msg->rep->flags) !=
403|		LDNS_RCODE_NOERROR &&
404|	   FLAGS_GET_RCODE(qstate->return_msg->rep->flags) !=
405|		LDNS_RCODE_NXDOMAIN &&
406|	   FLAGS_GET_RCODE(qstate->return_msg->rep->flags) !=
407|		LDNS_RCODE_YXDOMAIN)
408|		return 0;
409|	/* We don't store the reply if its TTL is 0 unless serve-expired is
410|	 * enabled.  Such a reply won't be reusable and simply be a waste for
411|	 * the backend.  It's also compatible with the default behavior of
412|	 * dns_cache_store_msg(). */
413|	if(qstate->return_msg->rep->ttl == 0 &&
414|		!qstate->env->cfg->serve_expired)
415|		return 0;
416|
417|	/* The EDE is added to the out-list so it is encoded in the cached message */
418|	if (qstate->env->cfg->ede && qstate->return_msg->rep->reason_bogus != LDNS_EDE_NONE) {
419|		edns_opt_list_append_ede(&edns.opt_list_out, qstate->env->scratch,
420|					qstate->return_msg->rep->reason_bogus,
421|					qstate->return_msg->rep->reason_bogus_str);
422|	}
423|
424|	if(verbosity >= VERB_ALGO)
425|		log_dns_msg("cachedb encoding", &qstate->return_msg->qinfo,
426|	                qstate->return_msg->rep);
427|	if(!reply_info_answer_encode(&qstate->return_msg->qinfo,
428|		qstate->return_msg->rep, 0, qstate->query_flags,
429|		buf, 0, 1, qstate->env->scratch, 65535, &edns, 1, 0))
430|		return 0;
431|
432|	/* TTLs in the return_msg are relative to time(0) so we have to
433|	 * store that, we also store the smallest ttl in the packet+time(0)
434|	 * as the packet expiry time */
435|	/* qstate->return_msg->rep->ttl contains that relative shortest ttl */
436|	timestamp = (uint64_t)*qstate->env->now;
437|	expiry = timestamp + (uint64_t)qstate->return_msg->rep->ttl;
438|	timestamp = htobe64(timestamp);
439|	expiry = htobe64(expiry);
440|	oldlim = sldns_buffer_limit(buf);
441|	if(oldlim + sizeof(timestamp)+sizeof(expiry) >=
442|		sldns_buffer_capacity(buf))
443|		return 0; /* doesn't fit. */
444|	sldns_buffer_set_limit(buf, oldlim + sizeof(timestamp)+sizeof(expiry));
445|	sldns_buffer_write_at(buf, oldlim, &timestamp, sizeof(timestamp));
446|	sldns_buffer_write_at(buf, oldlim+sizeof(timestamp), &expiry,
447|		sizeof(expiry));
448|
449|	return 1;
450|}

515|static int
516|parse_data(struct module_qstate* qstate, struct sldns_buffer* buf)
517|{
518|	struct msg_parse* prs;
519|	struct edns_data edns;
520|	struct edns_option* ede;
521|	uint64_t timestamp, expiry;
522|	time_t adjust;
523|	size_t lim = sldns_buffer_limit(buf);
524|	if(lim < LDNS_HEADER_SIZE+sizeof(timestamp)+sizeof(expiry))
525|		return 0; /* too short */
526|
527|	/* remove timestamp and expiry from end */
528|	sldns_buffer_read_at(buf, lim-sizeof(expiry), &expiry, sizeof(expiry));
529|	sldns_buffer_read_at(buf, lim-sizeof(expiry)-sizeof(timestamp),
530|		&timestamp, sizeof(timestamp));
531|	expiry = be64toh(expiry);
532|	timestamp = be64toh(timestamp);
533|
534|	/* parse DNS packet */
535|	regional_free_all(qstate->env->scratch);
536|	prs = (struct msg_parse*)regional_alloc(qstate->env->scratch,
537|		sizeof(struct msg_parse));
538|	if(!prs)
539|		return 0; /* out of memory */
540|	memset(prs, 0, sizeof(*prs));
541|	memset(&edns, 0, sizeof(edns));
542|	sldns_buffer_set_limit(buf, lim - sizeof(expiry)-sizeof(timestamp));
543|	if(parse_packet(buf, prs, qstate->env->scratch) != LDNS_RCODE_NOERROR) {
544|		sldns_buffer_set_limit(buf, lim);
545|		return 0;
546|	}
547|	if(parse_extract_edns_from_response_msg(prs, &edns, qstate->env->scratch) !=
548|		LDNS_RCODE_NOERROR) {
549|		sldns_buffer_set_limit(buf, lim);
550|		return 0;
551|	}
552|
553|	qstate->return_msg = dns_alloc_msg(buf, prs, qstate->region);
554|	sldns_buffer_set_limit(buf, lim);
555|	if(!qstate->return_msg)
556|		return 0;
557|	
558|	/* We find the EDE in the in-list after parsing */
559|	if(qstate->env->cfg->ede &&
560|		(ede = edns_opt_list_find(edns.opt_list_in, LDNS_EDNS_EDE))) {
561|		if(ede->opt_len >= 2) {
562|			qstate->return_msg->rep->reason_bogus =
563|				sldns_read_uint16(ede->opt_data);
564|		}
565|		/* allocate space and store the error string and it's size */
566|		if(ede->opt_len > 2) {
567|			size_t ede_len = ede->opt_len - 2;
568|			qstate->return_msg->rep->reason_bogus_str = regional_alloc(
569|				qstate->region, sizeof(char) * (ede_len+1));
570|			memcpy(qstate->return_msg->rep->reason_bogus_str,
571|				ede->opt_data+2, ede_len);
572|			qstate->return_msg->rep->reason_bogus_str[ede_len] = 0;
573|		}
574|	}
575|
576|	qstate->return_rcode = LDNS_RCODE_NOERROR;
577|
578|	/* see how much of the TTL expired, and remove it */
579|	if(*qstate->env->now <= (time_t)timestamp) {
580|		verbose(VERB_ALGO, "cachedb msg adjust by zero");
581|		return 1; /* message from the future (clock skew?) */
582|	}
583|	adjust = *qstate->env->now - (time_t)timestamp;
584|	if(qstate->return_msg->rep->ttl < adjust) {
585|		verbose(VERB_ALGO, "cachedb msg expired");
586|		/* If serve-expired is enabled, we still use an expired message
587|		 * setting the TTL to 0. */
588|		if(!qstate->env->cfg->serve_expired ||
589|			(FLAGS_GET_RCODE(qstate->return_msg->rep->flags)
590|			!= LDNS_RCODE_NOERROR &&
591|			FLAGS_GET_RCODE(qstate->return_msg->rep->flags)
592|			!= LDNS_RCODE_NXDOMAIN &&
593|			FLAGS_GET_RCODE(qstate->return_msg->rep->flags)
594|			!= LDNS_RCODE_YXDOMAIN))
595|			return 0; /* message expired */
596|		else
597|			adjust = -1;
598|	}
599|	verbose(VERB_ALGO, "cachedb msg adjusted down by %d", (int)adjust);
600|	adjust_msg_ttl(qstate->return_msg, adjust);
601|
602|	/* Similar to the unbound worker, if serve-expired is enabled and
603|	 * the msg would be considered to be expired, mark the state so a
604|	 * refetch will be scheduled.  The comparison between 'expiry' and
605|	 * 'now' should be redundant given how these values were calculated,
606|	 * but we check it just in case as does good_expiry_and_qinfo(). */
607|	if(qstate->env->cfg->serve_expired &&
608|		(adjust == -1 || (time_t)expiry < *qstate->env->now)) {
609|		qstate->need_refetch = 1;
610|	}
611|
612|	return 1;
613|}

626|static int
627|load_msg(RES* ssl, sldns_buffer* buf, struct worker* worker)
628|{
629|	struct regional* region = worker->scratchpad;
630|	struct query_info qinf;
631|	struct reply_info rep;
632|	char* s = (char*)sldns_buffer_begin(buf);
633|	unsigned int flags, qdcount, security, an, ns, ar;
634|	long long ttl;
635|	size_t i;
636|	int go_on = 1;
637|	int ede;
638|	int consumed = 0;
639|	char* ede_str = NULL;
640|
641|	regional_free_all(region);
642|
643|	if(strncmp(s, "msg ", 4) != 0) {
644|		log_warn("error expected msg but got %s", s);
645|		return 0;
646|	}
647|	s += 4;
648|	s = load_qinfo(s, &qinf, region);
649|	if(!s) {
650|		return 0;
651|	}
652|
653|	/* read remainder of line */
654|	/* note the last space before any possible EDE text */
655|	if(sscanf(s, " %u %u " ARG_LL "d %u %u %u %u %d %n", &flags, &qdcount, &ttl,
656|		&security, &an, &ns, &ar, &ede, &consumed) != 8) {
657|		log_warn("error cannot parse numbers: %s", s);
658|		return 0;
659|	}
660|	/* there may be EDE text after the numbers */
661|	if(consumed > 0 && (size_t)consumed < strlen(s))
662|		ede_str = s + consumed;
663|	memset(&rep, 0, sizeof(rep));
664|	rep.flags = (uint16_t)flags;
665|	rep.qdcount = (uint16_t)qdcount;
666|	rep.ttl = (time_t)ttl;
667|	rep.prefetch_ttl = PREFETCH_TTL_CALC(rep.ttl);
668|	rep.serve_expired_ttl = rep.ttl + SERVE_EXPIRED_TTL;
669|	rep.security = (enum sec_status)security;
670|	if(an > RR_COUNT_MAX || ns > RR_COUNT_MAX || ar > RR_COUNT_MAX) {
671|		log_warn("error too many rrsets");
672|		return 0; /* protect against integer overflow in alloc */
673|	}
674|	rep.an_numrrsets = (size_t)an;
675|	rep.ns_numrrsets = (size_t)ns;
676|	rep.ar_numrrsets = (size_t)ar;
677|	rep.rrset_count = (size_t)an+(size_t)ns+(size_t)ar;
678|	rep.reason_bogus = (sldns_ede_code)ede;
679|	rep.reason_bogus_str = ede_str?(char*)regional_strdup(region, ede_str):NULL;
680|	rep.rrsets = (struct ub_packed_rrset_key**)regional_alloc_zero(
681|		region, sizeof(struct ub_packed_rrset_key*)*rep.rrset_count);
682|
683|	/* fill repinfo with references */
684|	for(i=0; i<rep.rrset_count; i++) {
685|		if(!load_ref(ssl, buf, worker, region, &rep.rrsets[i], 
686|			&go_on)) {
687|			return 0;
688|		}
689|	}
690|
691|	if(!go_on) 
692|		return 1; /* skip this one, not all references satisfied */
693|
694|	if(!dns_cache_store(&worker->env, &qinf, &rep, 0, 0, 0, NULL, flags,
695|		*worker->env.now)) {
696|		log_warn("error out of memory");
697|		return 0;
698|	}
699|	return 1;
700|}

461|static int
462|answer_norec_from_cache(struct worker* worker, struct query_info* qinfo,
463|	uint16_t id, uint16_t flags, struct comm_reply* repinfo,
464|	struct edns_data* edns)
465|{
466|	/* for a nonrecursive query return either:
467|	 * 	o an error (servfail; we try to avoid this)
468|	 * 	o a delegation (closest we have; this routine tries that)
469|	 * 	o the answer (checked by answer_from_cache)
470|	 *
471|	 * So, grab a delegation from the rrset cache.
472|	 * Then check if it needs validation, if so, this routine fails,
473|	 * so that iterator can prime and validator can verify rrsets.
474|	 */
475|	uint16_t udpsize = edns->udp_size;
476|	int secure = 0;
477|	time_t timenow = *worker->env.now;
478|	int has_cd_bit = (flags&BIT_CD);
479|	int must_validate = (!has_cd_bit || worker->env.cfg->ignore_cd)
480|		&& worker->env.need_to_validate;
481|	struct dns_msg *msg = NULL;
482|	struct delegpt *dp;
483|
484|	dp = dns_cache_find_delegation(&worker->env, qinfo->qname,
485|		qinfo->qname_len, qinfo->qtype, qinfo->qclass,
486|		worker->scratchpad, &msg, timenow, 0, NULL, 0);
487|	if(!dp) { /* no delegation, need to reprime */
488|		return 0;
489|	}
490|	/* In case we have a local alias, copy it into the delegation message.
491|	 * Shallow copy should be fine, as we'll be done with msg in this
492|	 * function. */
493|	msg->qinfo.local_alias = qinfo->local_alias;
494|	if(must_validate) {
495|		switch(check_delegation_secure(msg->rep)) {
496|		case sec_status_unchecked:
497|			/* some rrsets have not been verified yet, go and
498|			 * let validator do that */
499|			return 0;
500|		case sec_status_bogus:
501|		case sec_status_secure_sentinel_fail:
502|			/* some rrsets are bogus, reply servfail */
503|			edns->edns_version = EDNS_ADVERTISED_VERSION;
504|			edns->udp_size = EDNS_ADVERTISED_SIZE;
505|			edns->ext_rcode = 0;
506|			edns->bits &= EDNS_DO;
507|			if(!inplace_cb_reply_servfail_call(&worker->env, qinfo, NULL,
508|				msg->rep, LDNS_RCODE_SERVFAIL, edns, repinfo, worker->scratchpad,
509|				worker->env.now_tv))
510|					return 0;
511|			/* Attach the cached EDE (RFC8914) */
512|			if(worker->env.cfg->ede &&
513|				msg->rep->reason_bogus != LDNS_EDE_NONE) {
514|				edns_opt_list_append_ede(&edns->opt_list_out,
515|					worker->scratchpad, msg->rep->reason_bogus,
516|					msg->rep->reason_bogus_str);
517|			}
518|			error_encode(repinfo->c->buffer, LDNS_RCODE_SERVFAIL,
519|				&msg->qinfo, id, flags, edns);
520|			if(worker->stats.extended) {
521|				worker->stats.ans_bogus++;
522|				worker->stats.ans_rcode[LDNS_RCODE_SERVFAIL]++;
523|			}
524|			return 1;
525|		case sec_status_secure:
526|			/* all rrsets are secure */
527|			/* remove non-secure rrsets from the add. section*/
528|			if(worker->env.cfg->val_clean_additional)
529|				deleg_remove_nonsecure_additional(msg->rep);
530|			secure = 1;
531|			break;
532|		case sec_status_indeterminate:
533|		case sec_status_insecure:
534|		default:
535|			/* not secure */
536|			secure = 0;
537|			break;
538|		}
539|	}
540|	/* return this delegation from the cache */
541|	edns->edns_version = EDNS_ADVERTISED_VERSION;
542|	edns->udp_size = EDNS_ADVERTISED_SIZE;
543|	edns->ext_rcode = 0;
544|	edns->bits &= EDNS_DO;
545|	if(!inplace_cb_reply_cache_call(&worker->env, qinfo, NULL, msg->rep,
546|		(int)(flags&LDNS_RCODE_MASK), edns, repinfo, worker->scratchpad,
547|		worker->env.now_tv))
548|			return 0;
549|	msg->rep->flags |= BIT_QR|BIT_RA;
550|	/* Attach the cached EDE (RFC8914) if CD bit is set and the answer is
551|	 * bogus. */
552|	if(worker->env.cfg->ede && has_cd_bit &&
553|		(check_delegation_secure(msg->rep) == sec_status_bogus ||
554|		check_delegation_secure(msg->rep) == sec_status_secure_sentinel_fail) &&
555|		msg->rep->reason_bogus != LDNS_EDE_NONE) {
556|		edns_opt_list_append_ede(&edns->opt_list_out,
557|			worker->scratchpad, msg->rep->reason_bogus,
558|			msg->rep->reason_bogus_str);
559|	}
560|	if(!reply_info_answer_encode(&msg->qinfo, msg->rep, id, flags,
561|		repinfo->c->buffer, 0, 1, worker->scratchpad,
562|		udpsize, edns, (int)(edns->bits & EDNS_DO), secure)) {
563|		if(!inplace_cb_reply_servfail_call(&worker->env, qinfo, NULL, NULL,
564|			LDNS_RCODE_SERVFAIL, edns, repinfo, worker->scratchpad,
565|			worker->env.now_tv))
566|				edns->opt_list_inplace_cb_out = NULL;
567|		error_encode(repinfo->c->buffer, LDNS_RCODE_SERVFAIL,
568|			&msg->qinfo, id, flags, edns);
569|	}
570|	if(worker->stats.extended) {
571|		if(secure) worker->stats.ans_secure++;
572|		server_stats_insrcode(&worker->stats, repinfo->c->buffer);
573|	}
574|	return 1;
575|}

638|static int
639|answer_from_cache(struct worker* worker, struct query_info* qinfo,
640|	struct respip_client_info* cinfo, int* need_drop, int* is_expired_answer,
641|	int* is_secure_answer, struct ub_packed_rrset_key** alias_rrset,
642|	struct reply_info** partial_repp,
643|	struct reply_info* rep, uint16_t id, uint16_t flags,
644|	struct comm_reply* repinfo, struct edns_data* edns)
645|{
646|	time_t timenow = *worker->env.now;
647|	uint16_t udpsize = edns->udp_size;
648|	struct reply_info* encode_rep = rep;
649|	struct reply_info* partial_rep = *partial_repp;
650|	int has_cd_bit = (flags&BIT_CD);
651|	int must_validate = (!has_cd_bit || worker->env.cfg->ignore_cd)
652|		&& worker->env.need_to_validate;
653|	*partial_repp = NULL;  /* avoid accidental further pass */
654|
655|	/* Check TTL */
656|	if(rep->ttl < timenow) {
657|		/* Check if we need to serve expired now */
658|		if(worker->env.cfg->serve_expired &&
659|			!worker->env.cfg->serve_expired_client_timeout) {
660|				if(worker->env.cfg->serve_expired_ttl &&
661|					rep->serve_expired_ttl < timenow)
662|					return 0;
663|				/* Ignore expired failure answers */
664|				if(FLAGS_GET_RCODE(rep->flags) !=
665|					LDNS_RCODE_NOERROR &&
666|					FLAGS_GET_RCODE(rep->flags) !=
667|					LDNS_RCODE_NXDOMAIN &&
668|					FLAGS_GET_RCODE(rep->flags) !=
669|					LDNS_RCODE_YXDOMAIN)
670|					return 0;
671|				if(!rrset_array_lock(rep->ref, rep->rrset_count, 0))
672|					return 0;
673|				*is_expired_answer = 1;
674|		} else {
675|			/* the rrsets may have been updated in the meantime.
676|			 * we will refetch the message format from the
677|			 * authoritative server
678|			 */
679|			return 0;
680|		}
681|	} else {
682|		if(!rrset_array_lock(rep->ref, rep->rrset_count, timenow))
683|			return 0;
684|	}
685|	/* locked and ids and ttls are OK. */
686|
687|	/* check CNAME chain (if any) */
688|	if(rep->an_numrrsets > 0 && (rep->rrsets[0]->rk.type ==
689|		htons(LDNS_RR_TYPE_CNAME) || rep->rrsets[0]->rk.type ==
690|		htons(LDNS_RR_TYPE_DNAME))) {
691|		if(!reply_check_cname_chain(qinfo, rep)) {
692|			/* cname chain invalid, redo iterator steps */
693|			verbose(VERB_ALGO, "Cache reply: cname chain broken");
694|			goto bail_out;
695|		}
696|	}
697|	/* check security status of the cached answer */
698|	if(must_validate && (rep->security == sec_status_bogus ||
699|		rep->security == sec_status_secure_sentinel_fail)) {
700|		/* BAD cached */
701|		edns->edns_version = EDNS_ADVERTISED_VERSION;
702|		edns->udp_size = EDNS_ADVERTISED_SIZE;
703|		edns->ext_rcode = 0;
704|		edns->bits &= EDNS_DO;
705|		if(!inplace_cb_reply_servfail_call(&worker->env, qinfo, NULL, rep,
706|			LDNS_RCODE_SERVFAIL, edns, repinfo, worker->scratchpad,
707|			worker->env.now_tv))
708|			goto bail_out;
709|		/* Attach the cached EDE (RFC8914) */
710|		if(worker->env.cfg->ede && rep->reason_bogus != LDNS_EDE_NONE) {
711|			edns_opt_list_append_ede(&edns->opt_list_out,
712|					worker->scratchpad, rep->reason_bogus,
713|					rep->reason_bogus_str);
714|		}
715|		error_encode(repinfo->c->buffer, LDNS_RCODE_SERVFAIL,
716|			qinfo, id, flags, edns);
717|		rrset_array_unlock_touch(worker->env.rrset_cache,
718|			worker->scratchpad, rep->ref, rep->rrset_count);
719|		if(worker->stats.extended) {
720|			worker->stats.ans_bogus ++;
721|			worker->stats.ans_rcode[LDNS_RCODE_SERVFAIL] ++;
722|		}
723|		return 1;
724|	} else if(rep->security == sec_status_unchecked && must_validate) {
725|		verbose(VERB_ALGO, "Cache reply: unchecked entry needs "
726|			"validation");
727|		goto bail_out; /* need to validate cache entry first */
728|	} else if(rep->security == sec_status_secure) {
729|		if(reply_all_rrsets_secure(rep)) {
730|			*is_secure_answer = 1;
731|		} else {
732|			if(must_validate) {
733|				verbose(VERB_ALGO, "Cache reply: secure entry"
734|					" changed status");
735|				goto bail_out; /* rrset changed, re-verify */
736|			}
737|			*is_secure_answer = 0;
738|		}
739|	} else *is_secure_answer = 0;
740|
741|	edns->edns_version = EDNS_ADVERTISED_VERSION;
742|	edns->udp_size = EDNS_ADVERTISED_SIZE;
743|	edns->ext_rcode = 0;
744|	edns->bits &= EDNS_DO;
745|	*alias_rrset = NULL; /* avoid confusion if caller set it to non-NULL */
746|	if((worker->daemon->use_response_ip || worker->daemon->use_rpz) &&
747|		!partial_rep && !apply_respip_action(worker, qinfo, cinfo, rep,
748|		&repinfo->client_addr, repinfo->client_addrlen, alias_rrset,
749|		&encode_rep, worker->env.auth_zones)) {
750|		goto bail_out;
751|	} else if(partial_rep &&
752|		!respip_merge_cname(partial_rep, qinfo, rep, cinfo,
753|		must_validate, &encode_rep, worker->scratchpad,
754|		worker->env.auth_zones)) {
755|		goto bail_out;
756|	}
757|	if(encode_rep != rep) {
758|		/* if rewritten, it can't be considered "secure" */
759|		*is_secure_answer = 0;
760|	}
761|	if(!encode_rep || *alias_rrset) {
762|		if(!encode_rep)
763|			*need_drop = 1;
764|		else {
765|			/* If a partial CNAME chain is found, we first need to
766|			 * make a copy of the reply in the scratchpad so we
767|			 * can release the locks and lookup the cache again. */
768|			*partial_repp = reply_info_copy(encode_rep, NULL,
769|				worker->scratchpad);
770|			if(!*partial_repp)
771|				goto bail_out;
772|		}
773|	} else {
774|		if(*is_expired_answer == 1 &&
775|			worker->env.cfg->ede_serve_expired && worker->env.cfg->ede) {
776|			EDNS_OPT_LIST_APPEND_EDE(&edns->opt_list_out,
777|				worker->scratchpad, LDNS_EDE_STALE_ANSWER, "");
778|		}
779|		/* Attach the cached EDE (RFC8914) if CD bit is set and the
780|		 * answer is bogus. */
781|		if(*is_secure_answer == 0 &&
782|			worker->env.cfg->ede && has_cd_bit &&
783|			encode_rep->reason_bogus != LDNS_EDE_NONE) {
784|			edns_opt_list_append_ede(&edns->opt_list_out,
785|				worker->scratchpad, encode_rep->reason_bogus,
786|				encode_rep->reason_bogus_str);
787|		}
788|		if(!inplace_cb_reply_cache_call(&worker->env, qinfo, NULL, encode_rep,
789|			(int)(flags&LDNS_RCODE_MASK), edns, repinfo, worker->scratchpad,
790|			worker->env.now_tv))
791|			goto bail_out;
792|		if(!reply_info_answer_encode(qinfo, encode_rep, id, flags,
793|			repinfo->c->buffer, timenow, 1, worker->scratchpad,
794|			udpsize, edns, (int)(edns->bits & EDNS_DO),
795|			*is_secure_answer)) {
796|			if(!inplace_cb_reply_servfail_call(&worker->env, qinfo,
797|				NULL, NULL, LDNS_RCODE_SERVFAIL, edns, repinfo,
798|				worker->scratchpad, worker->env.now_tv))
799|					edns->opt_list_inplace_cb_out = NULL;
800|			error_encode(repinfo->c->buffer, LDNS_RCODE_SERVFAIL,
801|				qinfo, id, flags, edns);
802|		}
803|	}
804|	/* cannot send the reply right now, because blocking network syscall
805|	 * is bad while holding locks. */
806|	rrset_array_unlock_touch(worker->env.rrset_cache, worker->scratchpad,
807|		rep->ref, rep->rrset_count);
808|	/* go and return this buffer to the client */
809|	return 1;
810|
811|bail_out:
812|	rrset_array_unlock_touch(worker->env.rrset_cache,
813|		worker->scratchpad, rep->ref, rep->rrset_count);
814|	return 0;
815|}

1102|static int
1103|deny_refuse(struct comm_point* c, enum acl_access acl,
1104|	enum acl_access deny, enum acl_access refuse,
1105|	struct worker* worker, struct comm_reply* repinfo,
1106|	struct acl_addr* acladdr, int ede,
1107|	struct check_request_result* check_result)
1108|{
1109|	if(acl == deny) {
1110|		if(verbosity >= VERB_ALGO) {
1111|			log_acl_action("dropped", &repinfo->client_addr,
1112|				repinfo->client_addrlen, acl, acladdr);
1113|			log_buf(VERB_ALGO, "dropped", c->buffer);
1114|		}
1115|		comm_point_drop_reply(repinfo);
1116|		if(worker->stats.extended)
1117|			worker->stats.unwanted_queries++;
