3895|	/* we have finished processing this query */
3896|	qstate->ext_state[id] = module_finished;
3897|
3898|	/* TODO:  we are using a private TTL, trim the response. */
3899|	/* if (mPrivateTTL > 0){IterUtils.setPrivateTTL(resp, mPrivateTTL); } */
3900|
3901|	/* prepend any items we have accumulated */
3902|	if(iq->an_prepend_list || iq->ns_prepend_list) {
3903|		if(!iter_prepend(iq, iq->response, qstate->region)) {
