2089|	 * subnetmod) ignore stale data from the main cache. */
2090|	if(qstate->no_cache_lookup || qstate->is_drop) {
2091|		verbose(VERB_ALGO,
2092|			"Serve expired: Not allowed to look into cache for stale");
2093|		return;
2094|	}
