2194|			else
2195|				qstate->env->mesh->rpz_action[
2196|					respip_action_to_rpz_action(actinfo.action)] += i;
2197|		}
2198|	}
2199|
2200|	/* Mesh area accounting */
2201|	if(mstate->reply_list) {
2202|		mstate->reply_list = NULL;
2203|		if(!mstate->reply_list && !mstate->cb_list) {
2204|			log_assert(mesh->num_reply_states > 0);
2205|			mesh->num_reply_states--;
2206|			if(mstate->super_set.count == 0) {
2207|				mesh->num_detached_states++;
2208|			}
2209|		}
2210|	}
2211|
2212|	while((c = mstate->cb_list) != NULL) {
