1027|	size_t txt_len = txt ? strlen(txt) : 0;
1028|
1029|	/* allocate new element */
1030|	opt = (struct edns_option*)regional_alloc(region, sizeof(*opt));
1031|	if(!opt)
1032|		return 0;
1033|	opt->next = NULL;
1034|	opt->opt_code = LDNS_EDNS_EDE;
