1514|static int
1515|processInit(struct module_qstate* qstate, struct val_qstate* vq, 
1516|	struct val_env* ve, int id)
1517|{
1518|	uint8_t* lookup_name;
1519|	size_t lookup_len;
1520|	struct trust_anchor* anchor;
1521|	enum val_classification subtype = val_classify_response(
1522|		qstate->query_flags, &qstate->qinfo, &vq->qchase, 
1523|		vq->orig_msg->rep, vq->rrset_skip);
1524|	if(vq->restart_count > ve->max_restart) {
1525|		verbose(VERB_ALGO, "restart count exceeded");
1526|		return val_error(qstate, id);
1527|	}
1528|
1529|	/* correctly initialize reason_bogus */
1530|	update_reason_bogus(vq->chase_reply, LDNS_EDE_DNSSEC_BOGUS);
1531|
1532|	verbose(VERB_ALGO, "validator classification %s", 
1533|		val_classification_to_string(subtype));
1534|	if(subtype == VAL_CLASS_REFERRAL && 
1535|		vq->rrset_skip < vq->orig_msg->rep->rrset_count) {
1536|		/* referral uses the rrset name as qchase, to find keys for
1537|		 * that rrset */
1538|		vq->qchase.qname = vq->orig_msg->rep->
1539|			rrsets[vq->rrset_skip]->rk.dname;
1540|		vq->qchase.qname_len = vq->orig_msg->rep->
1541|			rrsets[vq->rrset_skip]->rk.dname_len;
1542|		vq->qchase.qtype = ntohs(vq->orig_msg->rep->
1543|			rrsets[vq->rrset_skip]->rk.type);
1544|		vq->qchase.qclass = ntohs(vq->orig_msg->rep->
1545|			rrsets[vq->rrset_skip]->rk.rrset_class);
1546|	}
1547|	lookup_name = vq->qchase.qname;
1548|	lookup_len = vq->qchase.qname_len;
1549|	/* for type DS look at the parent side for keys/trustanchor */
1550|	/* also for NSEC not at apex */
1551|	if(vq->qchase.qtype == LDNS_RR_TYPE_DS ||
1552|		(vq->qchase.qtype == LDNS_RR_TYPE_NSEC && 
1553|		 vq->orig_msg->rep->rrset_count > vq->rrset_skip &&
1554|		 ntohs(vq->orig_msg->rep->rrsets[vq->rrset_skip]->rk.type) ==
1555|		 LDNS_RR_TYPE_NSEC &&
1556|		 !(vq->orig_msg->rep->rrsets[vq->rrset_skip]->
1557|		 rk.flags&PACKED_RRSET_NSEC_AT_APEX))) {
1558|		dname_remove_label(&lookup_name, &lookup_len);
1559|	}
1560|
1561|	val_mark_indeterminate(vq->chase_reply, qstate->env->anchors, 
1562|		qstate->env->rrset_cache, qstate->env);
1563|	vq->key_entry = NULL;
1564|	vq->empty_DS_name = NULL;
1565|	vq->ds_rrset = 0;
1566|	anchor = anchors_lookup(qstate->env->anchors, 
1567|		lookup_name, lookup_len, vq->qchase.qclass);
1568|
1569|	/* Determine the signer/lookup name */
1570|	val_find_signer(subtype, &vq->qchase, vq->orig_msg->rep, 
1571|		vq->rrset_skip, &vq->signer_name, &vq->signer_len);
1572|	if(vq->signer_name != NULL &&
1573|		!dname_subdomain_c(lookup_name, vq->signer_name)) {
1574|		log_nametypeclass(VERB_ALGO, "this signer name is not a parent "
1575|			"of lookupname, omitted", vq->signer_name, 0, 0);
1576|		vq->signer_name = NULL;
1577|	}
1578|	if(vq->signer_name == NULL) {
1579|		log_nametypeclass(VERB_ALGO, "no signer, using", lookup_name,
1580|			0, 0);
1581|	} else {
1582|		lookup_name = vq->signer_name;
1583|		lookup_len = vq->signer_len;
1584|		log_nametypeclass(VERB_ALGO, "signer is", lookup_name, 0, 0);
1585|	}
1586|
1587|	/* for NXDOMAIN it could be signed by a parent of the trust anchor */
1588|	if(subtype == VAL_CLASS_NAMEERROR && vq->signer_name &&
1589|		anchor && dname_strict_subdomain_c(anchor->name, lookup_name)){
1590|		lock_basic_unlock(&anchor->lock);
1591|		anchor = anchors_lookup(qstate->env->anchors, 
1592|			lookup_name, lookup_len, vq->qchase.qclass);
1593|		if(!anchor) { /* unsigned parent denies anchor*/
1594|			verbose(VERB_QUERY, "unsigned parent zone denies"
1595|				" trust anchor, indeterminate");
1596|			vq->chase_reply->security = sec_status_indeterminate;
1597|			update_reason_bogus(vq->chase_reply, LDNS_EDE_DNSSEC_INDETERMINATE);
1598|			vq->state = VAL_FINISHED_STATE;
1599|			return 1;
1600|		}
1601|		verbose(VERB_ALGO, "trust anchor NXDOMAIN by signed parent");
1602|	} else if(subtype == VAL_CLASS_POSITIVE &&
1603|		qstate->qinfo.qtype == LDNS_RR_TYPE_DNSKEY &&
1604|		query_dname_compare(lookup_name, qstate->qinfo.qname) == 0) {
1605|		/* is a DNSKEY so lookup a bit higher since we want to
1606|		 * get it from a parent or from trustanchor */
1607|		dname_remove_label(&lookup_name, &lookup_len);
1608|	}
1609|
1610|	if(vq->rrset_skip > 0 || subtype == VAL_CLASS_CNAME ||
1611|		subtype == VAL_CLASS_REFERRAL) {
1612|		/* extract this part of orig_msg into chase_reply for
1613|		 * the eventual VALIDATE stage */
1614|		val_fill_reply(vq->chase_reply, vq->orig_msg->rep, 
1615|			vq->rrset_skip, lookup_name, lookup_len, 
1616|			vq->signer_name);
1617|		if(verbosity >= VERB_ALGO)
1618|			log_dns_msg("chased extract", &vq->qchase, 
1619|				vq->chase_reply);
1620|	}
1621|
1622|	vq->key_entry = key_cache_obtain(ve->kcache, lookup_name, lookup_len,
1623|		vq->qchase.qclass, qstate->region, *qstate->env->now);
1624|
1625|	/* there is no key and no trust anchor */
1626|	if(vq->key_entry == NULL && anchor == NULL) {
1627|		/*response isn't under a trust anchor, so we cannot validate.*/
1628|		vq->chase_reply->security = sec_status_indeterminate;
1629|		update_reason_bogus(vq->chase_reply, LDNS_EDE_DNSSEC_INDETERMINATE);
1630|		/* go to finished state to cache this result */
1631|		vq->state = VAL_FINISHED_STATE;
1632|		return 1;
1633|	}
1634|	/* if not key, or if keyentry is *above* the trustanchor, i.e.
1635|	 * the keyentry is based on another (higher) trustanchor */
1636|	else if(vq->key_entry == NULL || (anchor &&
1637|		dname_strict_subdomain_c(anchor->name, vq->key_entry->name))) {
1638|		/* trust anchor is an 'unsigned' trust anchor */
1639|		if(anchor && anchor->numDS == 0 && anchor->numDNSKEY == 0) {
1640|			vq->chase_reply->security = sec_status_insecure;
1641|			val_mark_insecure(vq->chase_reply, anchor->name, 
1642|				qstate->env->rrset_cache, qstate->env);
1643|			lock_basic_unlock(&anchor->lock);
1644|			/* go to finished state to cache this result */
1645|			vq->state = VAL_FINISHED_STATE;
1646|			return 1;
1647|		}
1648|		/* fire off a trust anchor priming query. */
1649|		verbose(VERB_DETAIL, "prime trust anchor");
1650|		if(!prime_trust_anchor(qstate, vq, id, anchor)) {
1651|			lock_basic_unlock(&anchor->lock);
1652|			return val_error(qstate, id);
1653|		}
1654|		lock_basic_unlock(&anchor->lock);
1655|		/* and otherwise, don't continue processing this event.
1656|		 * (it will be reactivated when the priming query returns). */
1657|		vq->state = VAL_FINDKEY_STATE;
1658|		return 0;
1659|	}
1660|	if(anchor) {
1661|		lock_basic_unlock(&anchor->lock);
1662|	}
1663|
1664|	if(key_entry_isnull(vq->key_entry)) {
1665|		/* response is under a null key, so we cannot validate
1666|		 * However, we do set the status to INSECURE, since it is 
1667|		 * essentially proven insecure. */
1668|		vq->chase_reply->security = sec_status_insecure;
1669|		val_mark_insecure(vq->chase_reply, vq->key_entry->name, 
1670|			qstate->env->rrset_cache, qstate->env);
1671|		/* go to finished state to cache this result */
1672|		vq->state = VAL_FINISHED_STATE;
1673|		return 1;
1674|	} else if(key_entry_isbad(vq->key_entry)) {
1675|		/* Bad keys should have the relevant EDE code and text */
1676|		sldns_ede_code ede = key_entry_get_reason_bogus(vq->key_entry);
1677|		/* key is bad, chain is bad, reply is bogus */
1678|		errinf_dname(qstate, "key for validation", vq->key_entry->name);
1679|		errinf_ede(qstate, "is marked as invalid", ede);
1680|		errinf(qstate, "because of a previous");
1681|		errinf(qstate, key_entry_get_reason(vq->key_entry));
1682|
1683|		/* no retries, stop bothering the authority until timeout */
1684|		vq->restart_count = ve->max_restart;
1685|		vq->chase_reply->security = sec_status_bogus;
1686|		update_reason_bogus(vq->chase_reply, ede);
1687|		vq->state = VAL_FINISHED_STATE;
1688|		return 1;
1689|	}
1690|
1691|	/* otherwise, we have our "closest" cached key -- continue 
1692|	 * processing in the next state. */
1693|	vq->state = VAL_FINDKEY_STATE;
1694|	return 1;
1695|}

4222|void 
4223|iter_operate(struct module_qstate* qstate, enum module_ev event, int id,
4224|	struct outbound_entry* outbound)
4225|{
4226|	struct iter_env* ie = (struct iter_env*)qstate->env->modinfo[id];
4227|	struct iter_qstate* iq = (struct iter_qstate*)qstate->minfo[id];
4228|	verbose(VERB_QUERY, "iterator[module %d] operate: extstate:%s event:%s", 
4229|		id, strextstate(qstate->ext_state[id]), strmodulevent(event));
4230|	if(iq) log_query_info(VERB_QUERY, "iterator operate: query", 
4231|		&qstate->qinfo);
4232|	if(iq && qstate->qinfo.qname != iq->qchase.qname)
4233|		log_query_info(VERB_QUERY, "iterator operate: chased to", 
4234|			&iq->qchase);
4235|
4236|	/* perform iterator state machine */
4237|	if((event == module_event_new || event == module_event_pass) && 
4238|		iq == NULL) {
4239|		if(!iter_new(qstate, id)) {
4240|			errinf(qstate, "malloc failure, new iterator module allocation");
4241|			(void)error_response(qstate, id, LDNS_RCODE_SERVFAIL);
4242|			return;
4243|		}
4244|		iq = (struct iter_qstate*)qstate->minfo[id];
4245|		process_request(qstate, iq, ie, id);
4246|		return;
4247|	}
4248|	if(iq && event == module_event_pass) {
4249|		iter_handle(qstate, iq, ie, id);
4250|		return;
4251|	}
4252|	if(iq && outbound) {
4253|		process_response(qstate, iq, ie, id, outbound, event);
4254|		return;
4255|	}
4256|	if(event == module_event_error) {
4257|		verbose(VERB_ALGO, "got called with event error, giving up");
4258|		errinf(qstate, "iterator module got the error event");
4259|		(void)error_response(qstate, id, LDNS_RCODE_SERVFAIL);
4260|		return;
4261|	}
4262|
4263|	log_err("bad event for iterator");
4264|	errinf(qstate, "iterator module received wrong event");
4265|	(void)error_response(qstate, id, LDNS_RCODE_SERVFAIL);
4266|}

114|int createResponse(struct module_qstate* qstate, sldns_buffer* pkt)
115|{
116|	struct msg_parse* prs;
117|	struct edns_data edns;
118|
119|	/* parse message */
120|	prs = (struct msg_parse*) regional_alloc(qstate->env->scratch,
121|		sizeof(struct msg_parse));
122|	if(!prs) {
123|		log_err("createResponse: out of memory on incoming message");
124|		return 0;
125|	}
126|
127|	memset(prs, 0, sizeof(*prs));
128|	memset(&edns, 0, sizeof(edns));
129|
130|	sldns_buffer_set_position(pkt, 0);
131|	if(parse_packet(pkt, prs, qstate->env->scratch) != LDNS_RCODE_NOERROR) {
132|		verbose(VERB_ALGO, "createResponse: parse error on reply packet");
133|		return 0;
134|	}
135|	/* edns is not examined, but removed from message to help cache */
136|	if(parse_extract_edns_from_response_msg(prs, &edns, qstate->env->scratch) !=
137|		LDNS_RCODE_NOERROR)
138|		return 0;
139|
140|	/* remove CD-bit, we asked for in case we handle validation ourself */
141|	prs->flags &= ~BIT_CD;
142|
143|	/* allocate response dns_msg in region */
144|	qstate->return_msg = (struct dns_msg*) regional_alloc(qstate->region,
145|		sizeof(struct dns_msg));
146|	if(!qstate->return_msg)
147|		return 0;
148|
149|	memset(qstate->return_msg, 0, sizeof(*qstate->return_msg));
150|	if(!parse_create_msg(pkt, prs, NULL, &(qstate->return_msg)->qinfo,
151|		&(qstate->return_msg)->rep, qstate->region)) {
152|		log_err("createResponse: malloc failure: allocating incoming dns_msg");
153|		return 0;
154|	}
155|
156|	/* Make sure that the RA flag is set (since the presence of
157|	* this module means that recursion is available) */
158|	/* qstate->return_msg->rep->flags |= BIT_RA; */
159|
160|	/* Clear the AA flag */
161|	/* FIXME: does this action go here or in some other module? */
162|	/*qstate->return_msg->rep->flags &= ~BIT_AA; */
163|
164|	/* make sure QR flag is on */
165|	/*qstate->return_msg->rep->flags |= BIT_QR; */
166|
167|	if(verbosity >= VERB_ALGO)
168|		log_dns_msg("createResponse: packet:", &qstate->return_msg->qinfo,
169|			qstate->return_msg->rep);
170|
171|	return 1;
